# slug, original note title, searchable concepts, explanation, small original example
NOTES = {
'Python': [
('python3-basic-syntax','缩进、语句块与 Python 程序入口','缩进 语法 入门 main', 'Python 用缩进划分语句块，同一层级保持相同缩进。脚本直接运行时 __name__ 为 __main__，可把启动逻辑放进入口判断，避免模块被导入时就执行业务代码。','def greet(name):\n    return f"你好，{name}"\n\nif __name__ == "__main__":\n    print(greet("学习者"))'),
('python3-data-type','可变与不可变：理解 Python 数据类型','类型 列表 字符串 可变 引用', '变量名绑定到对象；类型属于对象。列表、字典和集合可变，整数、字符串和元组不可变，但元组内部引用的可变对象仍可能改变。赋值给另一个变量通常不会复制对象。','notes = ["语法"]\nalias = notes\nalias.append("练习")\nprint(notes)  # 两个名字指向同一个列表'),
('python3-list','列表增删、切片与浅拷贝','list append 切片 复制', '列表是有序可变容器，适合维护一组条目。切片上界不包含在结果中。list.copy() 创建浅拷贝，嵌套列表仍会共享内部对象；需要完全独立的嵌套结构时可考虑 deepcopy。','topics = ["变量", "函数", "异常"]\ntopics.append("模块")\nprint(topics[1:3])\nbackup = topics.copy()'),
('python3-dictionary','字典如何按键保存和查找数据','dict key value get 键值', '字典以键值对组织信息，键必须可哈希。读取可能不存在的键时，用 get 提供默认值可避免 KeyError。字典适合表示一条知识的属性，不应依赖不明确的字段约定。','entry = {"title": "函数", "views": 0}\nentry["views"] += 1\nprint(entry.get("summary", "暂无摘要"))'),
('python3-set','用集合去重与求交集','set 去重 交集 差集', '集合用于成员判断和去重，不提供按位置取值。交集找出共同元素，差集找出只属于一侧的元素。若既要去重又保留首次出现顺序，可使用字典的键顺序。','studied = {"函数", "列表"}\nrequired = {"函数", "异常"}\nprint(required - studied)  # 还需学习的主题'),
('python3-loop','for、while、break 和 continue','循环 range 遍历 break continue', 'for 常用于遍历可迭代对象，while 根据条件重复。break 退出当前循环，continue 跳到下一次迭代。修改正在遍历的列表可能漏处理元素，通常应构建新列表。','scores = [48, 72, 90]\nfor score in scores:\n    if score < 60:\n        continue\n    print(score)'),
('python3-function','函数参数、返回值与可变默认值','def 参数 return 默认参数', '函数把可复用的步骤封装起来。可变默认参数只在定义时创建一次，容易在多次调用之间意外共享状态；可用 None 作为默认值，在函数内部创建新对象。','def add_topic(topic, items=None):\n    if items is None:\n        items = []\n    items.append(topic)\n    return items'),
('python-comprehensions','列表推导式：过滤和转换数据','推导式 列表 过滤 映射', '推导式适合表达简单的数据转换和过滤。逻辑过长或需要多步异常处理时，普通循环更便于阅读与调试。字典推导式可用于构建从编号到条目的索引。','names = ["Python", "Java", "C++"]\nlong_names = [name.lower() for name in names if len(name) > 3]'),
('python3-iterator-generator','生成器为什么适合逐条处理大数据','yield 迭代器 惰性 内存', '生成器通过 yield 暂停函数并保存执行位置，按需产生元素。它适合流式读取和逐条处理，不必一次构造完整列表；但通常只能遍历一次，需要重复使用时应重新创建。','def pages(total):\n    for number in range(1, total + 1):\n        yield number\n\nfor page in pages(3):\n    print(page)'),
('python3-errors-execptions','异常处理与 finally 清理资源','try except finally raise 错误', '捕获可以恢复的具体异常，比捕获所有异常更利于排查问题。finally 无论是否发生异常都会执行，常用于清理。对非法输入可以主动 raise，让上层决定怎样反馈。','try:\n    count = int("12")\nexcept ValueError:\n    count = 0\nfinally:\n    print("解析结束")'),
('python3-with-keyword','with 上下文管理与文件关闭','with open 文件 资源关闭', 'with 会调用上下文管理协议，即使代码块发生异常也会执行退出清理。打开文本文件时明确指定编码，可以减少不同操作系统之间的乱码问题。','with open("learning.txt", "w", encoding="utf-8") as file:\n    file.write("今天理解了生成器。")'),
('python3-json','JSON 与 Python 对象如何互相转换','json loads dumps 序列化 中文', 'JSON 是文本数据交换格式。loads 把 JSON 字符串解析为 Python 对象，dumps 生成字符串。ensure_ascii=False 便于直接阅读中文；解析外部数据后仍需检查字段和类型。','import json\ntext = json.dumps({"topic": "字典"}, ensure_ascii=False)\nentry = json.loads(text)'),
('python3-module','模块导入与组织代码','import 模块 包 复用', '模块通常对应一个 Python 文件，包把相关模块放在一起。将数据库操作、业务逻辑和接口拆开，可减少单个文件复杂度。避免模块间循环导入，也不要在导入阶段执行昂贵任务。','# helpers.py\ndef normalize(text):\n    return text.strip().lower()\n\n# 在其他模块使用：from helpers import normalize'),
('python3-class','类、实例与实例属性','class self 对象 构造 __init__', '类定义对象的行为，实例保存具体状态。实例方法中的 self 指向当前对象。每个对象独立的列表应在 __init__ 中创建，放在类级别会在实例间共享。','class Notebook:\n    def __init__(self, title):\n        self.title = title\n        self.pages = []'),
('python-type-hints','类型注解有什么作用','typing list Optional 类型检查 Python3.9', '类型注解帮助编辑器和静态检查工具理解接口，不会单独强制运行时校验。内置泛型 list[str] 需要 Python 3.9 及以上；旧版本可使用 typing.List[str]。','from typing import List\n\ndef titles(items: List[str]) -> List[str]:\n    return [item.strip() for item in items]'),
('python-asyncio','asyncio：异步适合哪些任务','async await 协程 IO 并发', '协程适合网络请求等等待型工作。await 在等待可异步执行的操作时允许其他任务推进；在协程中直接调用阻塞函数仍会阻塞事件循环。CPU 密集任务通常需要其他并行方案。','import asyncio\n\nasync def remind():\n    await asyncio.sleep(0.1)\n    return "继续学习"\n\nprint(asyncio.run(remind()))'),
],
'C++': [
('cpp-basic-syntax','C++ 程序入口与编译流程','main 编译 链接 iostream', 'C++ 源文件通常先编译再链接为可执行程序。main 是程序入口，标准库名称位于 std 命名空间。编译时启用警告有助于发现未初始化变量和可疑转换。','#include <iostream>\nint main() {\n    std::cout << "Start learning\\n";\n    return 0;\n}'),
('cpp-data-types','基本数据类型与初始化','int double bool 初始化', '整数、浮点数和布尔值表达不同的数据。类型的具体大小依赖实现，固定宽度整数可使用标准库提供的类型。优先初始化变量，避免读取未确定的值。','int chapters{6};\ndouble progress{0.25};\nbool completed{false};'),
('cpp-variable-scope','作用域、生命周期与局部变量','作用域 生命周期 局部 全局', '作用域决定名字在哪些位置可见，生命周期决定对象何时存在。返回局部对象的指针或引用会造成悬空访问。传值返回常能通过优化避免多余复制。','int next_page(int page) {\n    int result = page + 1;\n    return result;\n}'),
('cpp-functions','函数参数如何选择传值或传引用','函数 参数 const 引用', '小型值通常可直接传值。需要修改调用者对象时传非 const 引用；只读较大对象时可传 const 引用。接口应清楚表达是否会修改数据。','#include <string>\nstd::size_t title_size(const std::string& title) {\n    return title.size();\n}'),
('cpp-references','引用与指针的区别','引用 指针 地址 nullptr', '引用是已存在对象的别名，初始化后不能改为绑定另一对象。指针保存地址，可以为空或重新指向。无论使用哪种方式，都需要保证被引用对象仍然存活。','int page = 1;\nint& alias = page;\nint* pointer = &page;\nalias = 2;\nif (pointer != nullptr) { ++(*pointer); }'),
('cpp-pointers','指针解引用与悬空风险','指针 解引用 空指针 内存', '解引用指针前应确保它非空且仍指向有效对象。删除对象后继续使用其地址属于未定义行为。管理拥有关系时，优先采用容器和智能指针而非手动维护裸指针。','int total{12};\nint* address = &total;\n*address += 3;'),
('cpp-arrays','数组边界与长度','数组 越界 连续存储', '内置数组在连续内存中保存固定数量的同类元素。合法下标从零开始，越界访问属于未定义行为。需要可变长度时可选择 vector，需要固定长度时也可考虑 std::array。','int scores[3]{70, 80, 90};\nfor (int score : scores) {\n    // 对每个元素执行处理\n}'),
('cpp-strings','std::string 的拼接和读取','string 字符串 getline', 'std::string 管理字符序列并自动维护存储空间。getline 可读取包含空格的一整行。size 返回字符单元数量，对于 UTF-8 文本通常不等于汉字或可见字符数量。','#include <string>\nstd::string topic = "C++";\nstd::string title = topic + " notes";'),
('cpp-vector','vector 扩容与迭代器失效','vector 动态数组 push_back reserve', 'vector 提供连续存储和动态大小。扩容可能移动全部元素，使原有指针、引用和迭代器失效。提前知道大致数量时可 reserve 预留容量，但它不会改变 size。','#include <vector>\nstd::vector<int> pages;\npages.reserve(8);\npages.push_back(1);'),
('cpp-classes-objects','用类封装状态与行为','class 对象 public private', '类把数据和相关操作放在一起。private 限制直接访问内部状态，public 暴露稳定接口。封装应维护对象约束，而不只是为每个字段机械添加 getter 和 setter。','class Counter {\n    int value{0};\npublic:\n    void increment() { ++value; }\n    int get() const { return value; }\n};'),
('cpp-inheritance','继承与组合的选择','继承 基类 派生类 组合', '继承表示派生对象可以作为基类对象使用。若只是复用一个功能模块，组合通常更直接。通过基类指针删除派生对象时，基类应有合适的虚析构函数。','struct Resource {\n    virtual ~Resource() = default;\n};\nstruct Book : Resource {};'),
('cpp-polymorphism','virtual 如何实现运行时多态','多态 virtual override 动态绑定', '通过基类引用或指针调用虚函数，可以选择实际对象的实现。override 帮助编译器检查是否确实重写了基类虚函数。按值传递派生对象可能产生对象切片。','struct Item { virtual int pages() const = 0; virtual ~Item() = default; };\nstruct Note : Item { int pages() const override { return 1; } };'),
('cpp-templates','函数模板与类型复用','template 泛型 编译期', '模板描述一组与类型相关的实现，编译器根据实际类型实例化。模板参数仍必须支持代码中用到的操作。错误信息较长时，可以先检查类型是否满足所需操作。','template<class T>\nT larger(T left, T right) {\n    return left < right ? right : left;\n}'),
('cpp-libs-memory','unique_ptr 与 RAII 自动释放资源','智能指针 unique_ptr RAII 内存泄漏', 'RAII 把资源释放与对象生命周期绑定。unique_ptr 表示独占所有权，不能直接复制但可以移动；shared_ptr 用于共享所有权，需要注意循环引用。','#include <memory>\nauto chapter = std::make_unique<int>(12);\n// 离开作用域后自动释放'),
('cpp-exceptions-handling','C++ 异常与栈展开','try catch throw 异常 RAII', 'throw 报告无法在当前层处理的问题，catch 在合适层恢复或反馈。异常传播时，已构造的局部对象会按规则析构，因此资源应放入 RAII 对象中管理。','#include <stdexcept>\nint checked(int value) {\n    if (value < 0) throw std::invalid_argument("negative");\n    return value;\n}'),
('cpp-stl-tutorial','STL 的容器、迭代器与算法','STL sort 容器 算法 iterator', '容器负责保存数据，迭代器描述访问范围，算法执行通用操作。算法通常使用左闭右开的区间。排序前确认迭代器类型及容器满足算法要求。','#include <algorithm>\n#include <vector>\nstd::vector<int> order{3, 1, 2};\n// 在函数中调用：std::sort(order.begin(), order.end());'),
],
'Java': [
('java-basic-datatypes','基本类型和引用类型','int double boolean 引用类型', 'Java 基本类型直接表示数值或布尔值，引用类型变量保存对象引用。引用变量可以为 null，调用方法前需要处理缺失值。包装类型参与自动拆箱时也可能因 null 触发异常。','int count = 6;\nInteger optionalCount = null;\nint safeCount = optionalCount == null ? 0 : optionalCount;'),
('java-object-classes','类、对象与实例字段','class new 对象 封装', '类定义结构和行为，通过 new 创建实例。实例字段属于具体对象，static 字段属于类。集合等可变实例状态通常应独立创建，避免意外共享。','class Notebook {\n    private String title;\n    Notebook(String title) { this.title = title; }\n}'),
('java-constructor','构造方法与对象初始化','构造方法 this 初始化', '构造方法在创建对象时建立初始状态，名称与类名一致，没有返回类型。可以通过 this 调用同类其他构造方法，但调用必须位于构造方法的开始位置。','class Page {\n    private int number;\n    Page() { this(1); }\n    Page(int number) { this.number = number; }\n}'),
('java-methods','方法参数为何是按值传递','方法 参数 引用 传值', 'Java 始终按值传递参数。传递对象时复制的是引用值，所以方法可以修改该对象的状态；但把参数重新赋给另一个对象，不会改变调用者变量的绑定。','static void addTopic(java.util.List<String> items) {\n    items.add("异常处理");\n}'),
('java-string','字符串比较为什么使用 equals','String equals == 不可变', 'String 对象不可变。== 对引用类型比较是否指向同一对象，equals 用来比较字符串内容。常量字符串放在调用侧可简化 null 情况下的比较。','String topic = new String("Java");\nboolean sameContent = "Java".equals(topic);'),
('java-array','数组固定长度与边界检查','数组 length 下标 越界', '数组创建后长度固定，元素类型统一。访问越界会抛出异常。需要经常增加或删除元素时，ArrayList 往往比手动维护数组更方便。','int[] chapters = {2, 4, 6};\nfor (int value : chapters) {\n    System.out.println(value);\n}'),
('java-arraylist','ArrayList 如何保存有序数据','List ArrayList 动态数组 集合', 'ArrayList 适合按索引访问和在尾部追加元素。中间插入或删除通常需要移动后续元素。它不是线程安全容器，跨线程修改时需要额外的并发设计。','java.util.List<String> topics = new java.util.ArrayList<>();\ntopics.add("集合");\nSystem.out.println(topics.get(0));'),
('java-hashmap','HashMap 的键、值和查找','Map HashMap getOrDefault 哈希', 'HashMap 根据键定位值，不保证固定遍历顺序。自定义键需要正确实现 equals 与 hashCode，并避免在作为键期间改变参与比较的字段。','java.util.Map<String, Integer> visits = new java.util.HashMap<>();\nvisits.put("Java", 3);\nint count = visits.getOrDefault("Python", 0);'),
('java-hashset','HashSet 去重与集合成员判断','Set HashSet 去重 contains', 'HashSet 保存不重复元素，适合判断某个主题是否已出现。其去重依据是 equals 与 hashCode，而不是对象显示出来的文本。需要顺序时可以选择其他集合实现。','java.util.Set<String> studied = new java.util.HashSet<>();\nstudied.add("接口");\nstudied.add("接口");\nSystem.out.println(studied.size());'),
('java-generics','泛型如何减少类型转换错误','泛型 类型参数 List 编译检查', '泛型把元素类型纳入编译期检查，减少取值后强制转换的需要。Java 泛型具有类型擦除机制，不能把基本类型直接作为类型实参，应使用对应包装类型。','java.util.List<Integer> pages = new java.util.ArrayList<>();\npages.add(12);\nint first = pages.get(0);'),
('java-inheritance','继承、重写与 super','extends 继承 override super', '子类通过继承扩展父类行为，重写方法时可加 @Override 让编译器检查。构造器不会被继承，子类构造过程中会初始化父类部分。优先保持清晰的替换关系。','class Resource { String kind() { return "resource"; } }\nclass Note extends Resource {\n    @Override String kind() { return "note"; }\n}'),
('java-interfaces','接口如何解耦实现','interface implements 解耦 多态', '接口描述调用方依赖的能力，具体实现负责完成操作。面向接口编写业务代码，有利于替换数据库访问方式或在测试中使用替身。','interface Repository { String findTitle(int id); }\nclass MemoryRepository implements Repository {\n    public String findTitle(int id) { return "note-" + id; }\n}'),
('java-exceptions','受检异常与运行时异常','Exception try catch finally', '异常处理应区分预期可恢复的问题与编程错误。受检异常通常需要捕获或声明，运行时异常不强制声明。日志与用户提示承担不同用途，避免把内部细节直接当作界面反馈。','try {\n    Integer.parseInt("lesson");\n} catch (NumberFormatException error) {\n    System.out.println("请输入数字编号");\n}'),
('java-files-io','使用 try-with-resources 关闭文件','IO 文件 流 try-with-resources', '流用于顺序读写数据。实现 AutoCloseable 的资源可以交给 try-with-resources 自动关闭。文本读取时指定字符集，可以避免平台默认编码造成差异。','try (java.io.BufferedReader reader = java.nio.file.Files.newBufferedReader(\n        java.nio.file.Path.of("notes.txt"), java.nio.charset.StandardCharsets.UTF_8)) {\n    System.out.println(reader.readLine());\n}'),
('java-multithreading','线程共享状态为什么需要同步','Thread synchronized 并发 竞争', '多个线程同时修改共享状态，可能产生竞态条件。自增并不是天然原子操作。可根据场景选择同步锁、原子变量或线程安全容器，并尽量减少共享可变状态。','java.util.concurrent.atomic.AtomicInteger counter =\n    new java.util.concurrent.atomic.AtomicInteger();\ncounter.incrementAndGet();'),
('java-mysql-connect','JDBC 参数化查询与资源管理','JDBC MySQL PreparedStatement SQL注入', 'JDBC 用连接、预编译语句和结果集访问关系数据库。参数化查询将数据与 SQL 结构分离；连接、语句和结果集都应正确关闭。连接配置和密码应从运行环境读取。','// 在已有 Connection connection 上执行\ntry (java.sql.PreparedStatement statement = connection.prepareStatement(\n        "SELECT title FROM notes WHERE id = ?")) {\n    statement.setInt(1, 7);\n}'),
],
'FastAPI': [
('fastapi-step1','创建 FastAPI 应用并启动服务','FastAPI Uvicorn app main 启动', 'FastAPI 实例承载路由与配置，Uvicorn 负责启动 ASGI 服务。main:app 的前半部分是模块名，后半部分是应用对象名。开发时的热重载选项不宜直接作为生产进程管理方案。','from fastapi import FastAPI\napp = FastAPI()\n@app.get("/hello")\ndef hello():\n    return {"message": "你好，图书馆"}\n# 启动：uvicorn main:app --reload'),
('fastapi-route','GET、POST、PUT、PATCH 与 DELETE','HTTP 路由 GET POST PATCH', '路由把请求方法和路径映射到处理函数。GET 用于读取，POST 常用于创建，PUT 常用于完整替换，PATCH 常用于局部更新。不要在读取接口中混入意外的数据修改。','@app.patch("/notes/{note_id}")\ndef rename_note(note_id: int):\n    return {"id": note_id, "message": "局部更新示例"}'),
('fastapi-path-params','路径参数如何进行类型校验','路径参数 Path 422 参数', '路径中的占位符会按函数参数类型转换。声明为 int 的参数无法解析成整数时，会返回校验错误。数值范围等约束可以使用 Path 显式声明。','from fastapi import Path\n@app.get("/notes/{note_id}")\ndef get_note(note_id: int = Path(gt=0)):\n    return {"id": note_id}'),
('fastapi-query-params','查询参数与分页接口','Query 分页 keyword page 查询', '不在路径中的简单参数通常作为查询参数。分页参数应设置合理下限和上限。搜索条件属于读取条件，常通过 URL 查询字符串传递，便于记录和分享。','from fastapi import Query\n@app.get("/notes")\ndef notes(page: int = Query(1, ge=1), size: int = Query(20, ge=1, le=100)):\n    return {"page": page, "size": size}'),
('fastapi-request-body','请求体与 Pydantic 模型','请求体 JSON BaseModel 校验', 'Pydantic 模型描述 JSON 结构和字段约束。FastAPI 将请求体解析成模型后再调用函数。输入模型与数据库模型承担不同职责，不能直接把所有输入字段都作为可信数据。','from pydantic import BaseModel, Field\nclass NoteInput(BaseModel):\n    title: str = Field(min_length=1, max_length=100)\n    content: str\n@app.post("/notes")\ndef create_note(payload: NoteInput):\n    return payload.model_dump()'),
('fastapi-response-model','响应模型为什么能防止字段泄露','response_model 输出过滤 密码', '响应模型约束并过滤输出字段，使接口契约清楚。用户对象包含密码哈希等内部信息时，应使用专用输出模型。它还会影响自动生成的接口文档。','class UserOutput(BaseModel):\n    username: str\n@app.get("/profile", response_model=UserOutput)\ndef profile():\n    return {"username": "reader", "internal": "不应输出"}'),
('fastapi-status-code','状态码和响应正文是两回事','HTTP 200 201 404 422 状态码', '返回 {404} 并不会把 HTTP 状态设置为 404，而且它是集合而非字典。正常读取通常为 200，创建常用 201，资源不存在可抛出 HTTPException(404)。客户端应同时检查状态和正文。','from fastapi import HTTPException\n@app.get("/missing")\ndef missing():\n    raise HTTPException(status_code=404, detail="知识不存在")'),
('fastapi-path-operation-dependencies','Depends 如何管理共享依赖','依赖注入 Depends get_db Session', '依赖可以提供数据库会话、当前用户或公共校验。yield 依赖适合在请求完成后关闭资源。依赖注入能减少路由重复代码，但不会自动代替业务层的权限判断。','from fastapi import Depends\ndef get_settings():\n    return {"site": "library"}\n@app.get("/settings")\ndef settings(value: dict = Depends(get_settings)):\n    return value'),
('fastapi-error-handling','HTTPException 与业务错误反馈','异常处理 HTTPException detail', '预期的业务错误可转换为明确的 HTTPException。校验错误、认证失败和服务不可用应有不同状态，便于前端显示合适提示。内部异常细节应留在服务端日志。','from fastapi import HTTPException\ndef require_available(available: bool):\n    if not available:\n        raise HTTPException(503, "模型服务暂时不可用")'),
('fastapi-middleware','中间件的请求与响应顺序','middleware 日志 耗时 call_next', '中间件包围请求处理流程，适合计时、追踪和添加公共响应头。它应把请求继续交给 call_next，除非有意提前返回。全局共享逻辑与具体业务校验要保持清晰边界。','@app.middleware("http")\nasync def add_header(request, call_next):\n    response = await call_next(request)\n    response.headers["X-Library"] = "preview"\n    return response'),
('fastapi-cors','跨域配置与携带 Cookie','CORS Origin Cookie 跨域', '浏览器按协议、域名和端口判断来源。跨域响应需要明确允许的来源。携带 Cookie 的跨域场景不能把允许来源简单写成通配符，认证还需配合其他请求防护。','from fastapi.middleware.cors import CORSMiddleware\napp.add_middleware(CORSMiddleware, allow_origins=["http://localhost:5173"],\n    allow_credentials=True, allow_methods=["GET", "POST"], allow_headers=["Content-Type"])'),
('fastapi-file-upload','文件上传与 UploadFile','UploadFile 文件 上传 multipart', 'UploadFile 适合接收文件并通过异步接口读取。服务端仍需限制大小、检查内容并生成安全文件名。用户提供的文件名不能直接当作任意文件系统路径使用。','from fastapi import UploadFile\n@app.post("/upload")\nasync def upload(file: UploadFile):\n    head = await file.read(1024)\n    return {"filename": file.filename, "read_bytes": len(head)}'),
('fastapi-header-cookie','Header 和 Cookie 的读取方式','Header Cookie 会话 HttpOnly', '请求头和 Cookie 可通过专门参数读取。Cookie 只是一种传输机制，服务端还需验证会话是否合法以及是否过期。HttpOnly 可限制脚本读取 Cookie，但不能替代完整认证。','from fastapi import Cookie\n@app.get("/session-info")\ndef info(session_id: str = Cookie(default="")):\n    return {"has_session": bool(session_id)}'),
('fastapi-security','认证和授权分别解决什么问题','认证 授权 登录 权限 OAuth2', '认证确认访问者是谁，授权决定其能访问什么。登录成功并不意味着能读取他人的私有知识。应在数据库查询范围中加入用户条件，而不是读取全部后仅在前端隐藏。','def can_edit(user_id: int, owner_id: int) -> bool:\n    return user_id == owner_id'),
('fastapi-testing','用 TestClient 检查接口行为','测试 TestClient pytest 接口', '接口测试应覆盖成功响应、非法输入和未授权访问。依赖替换可以让测试使用独立数据库或模拟外部服务，避免测试调用付费模型或修改真实数据。','from fastapi.testclient import TestClient\nclient = TestClient(app)\ndef test_hello():\n    response = client.get("/hello")\n    assert response.status_code == 200'),
('fastapi-sql-database','路由、服务层和数据库会话如何分工','SQLAlchemy 数据库 CRUD router service', '路由负责处理 HTTP 输入与错误，服务层组织业务规则，数据库访问层完成查询和写入。会话通常按请求创建并释放；事务需要在失败时回滚，避免后续请求继承无效状态。','def get_db():\n    db = SessionLocal()\n    try:\n        yield db\n    finally:\n        db.close()'),
],
'MySQL': [
('mysql-data-types','整数、定点数和文本类型怎么选','类型 INT DECIMAL VARCHAR utf8mb4', '按业务范围选字段类型。金额等需要精确十进制计算的数据通常使用 DECIMAL，而不是浮点数。字符串长度、字符集与排序规则会影响存储和比较；中文及表情通常使用 utf8mb4。','CREATE TABLE reading_progress (\n    id INT PRIMARY KEY,\n    title VARCHAR(120) NOT NULL,\n    ratio DECIMAL(5,2)\n);'),
('mysql-create-tables','主键、外键和非空约束','CREATE TABLE PRIMARY KEY FOREIGN KEY', '主键标识一条记录，非空和唯一约束保护数据质量。外键维护相关表之间的引用关系。设计知识库时，应把知识正文、分类和用户拆成合适的关联表。','CREATE TABLE learning_topics (\n    id INT PRIMARY KEY AUTO_INCREMENT,\n    name VARCHAR(80) NOT NULL UNIQUE\n);'),
('mysql-insert-query','INSERT 与明确字段列表','插入 INSERT VALUES', '插入数据时显式列出字段，避免表结构调整改变写入含义。批量插入可降低往返开销。应用代码应使用数据库驱动的参数绑定，而不是拼接用户输入。','INSERT INTO learning_topics (name)\nVALUES (\'Python\'), (\'Docker\');'),
('mysql-select-query','SELECT 投影与结果数量','查询 SELECT LIMIT 字段', 'SELECT 选出需要的列。列表接口只读取必要字段可降低传输量。使用 LIMIT 限制结果时，通常需要明确排序以获得可解释、可复现的分页顺序。','SELECT id, name\nFROM learning_topics\nORDER BY id\nLIMIT 10;'),
('mysql-where-clause','WHERE 的 AND、OR 与括号','条件 AND OR 优先级 过滤', 'AND 要求同时满足条件，OR 表示满足任一分支。组合条件时明确添加括号，尤其要保证用户权限条件作用于所有搜索分支，避免一个 OR 绕过访问限制。','SELECT id, title FROM notes\nWHERE owner_id = 7\n  AND (title LIKE \'%函数%\' OR summary LIKE \'%函数%\');'),
('mysql-update-query','UPDATE 前先确认筛选范围','UPDATE SET WHERE 更新', 'UPDATE 修改匹配条件的记录。漏写 WHERE 可能影响全表，因此可先用相同条件 SELECT 预览。重要修改放入事务，并在提交前检查影响行数。','UPDATE notes\nSET title = \'新的学习笔记\'\nWHERE id = 7 AND owner_id = 3;'),
('mysql-delete-query','物理删除与软删除的区别','DELETE 软删除 status', 'DELETE 从表中移除行，相关外键会影响是否能执行。软删除保留记录并修改状态，便于恢复和审计，但所有读取入口必须一致过滤已删除状态。','UPDATE notes\nSET status = \'archived\'\nWHERE id = 7;'),
('mysql-like-clause','LIKE 模糊匹配与通配符','LIKE 模糊搜索 通配符 索引', 'LIKE 中 % 匹配任意长度字符串，_ 匹配单个字符。把整个问题当连续子串搜索，容易漏掉不同表述。前置通配符也常影响普通 B-tree 索引的利用。','SELECT id, title FROM notes\nWHERE title LIKE \'Python%\';'),
('mysql-order-by','排序与稳定分页','ORDER BY LIMIT OFFSET 分页', '分页前应固定排序规则；当主排序字段重复时，可增加唯一编号作为第二排序键。深分页 OFFSET 可能扫描大量行，数据量大时可考虑基于上页游标继续读取。','SELECT id, title FROM notes\nORDER BY updated_at DESC, id DESC\nLIMIT 20 OFFSET 20;'),
('mysql-group-by-statement','GROUP BY、COUNT 和 HAVING','聚合 分组 COUNT HAVING', 'GROUP BY 把记录按字段归组，聚合函数计算每组统计。WHERE 在分组前筛选行，HAVING 根据分组结果筛选。选择非聚合列时应满足数据库分组规则。','SELECT category_id, COUNT(*) AS amount\nFROM notes\nGROUP BY category_id\nHAVING COUNT(*) >= 5;'),
('mysql-join','INNER JOIN 与 LEFT JOIN','JOIN 关联 LEFT 空值', 'INNER JOIN 只返回满足连接条件的组合，LEFT JOIN 保留左表没有匹配的行。右表过滤条件写在 WHERE 中，可能把外连接效果改变为只保留匹配行。','SELECT n.title, c.name\nFROM notes AS n\nLEFT JOIN categories AS c ON c.id = n.category_id;'),
('mysql-null','为什么不能使用等号比较 NULL','NULL IS NULL COALESCE 三值逻辑', 'NULL 表示缺失或未知。比较表达式中遇到 NULL 可能得到未知值，而非真假，因此应使用 IS NULL 或 IS NOT NULL。COALESCE 可以在显示时提供替代值。','SELECT title, COALESCE(summary, \'暂无摘要\')\nFROM notes\nWHERE source_url IS NULL;'),
('mysql-index','B-tree 索引与联合索引','索引 联合索引 EXPLAIN 查询优化', '索引用额外存储和写入成本换取特定查询效率。联合索引要结合过滤与排序方式设计，常见利用方式受最左前缀等规则影响。用 EXPLAIN 检查计划，比只凭字段名称猜测更可靠。','CREATE INDEX idx_notes_owner_time\nON notes (owner_id, updated_at);'),
('mysql-transaction','事务、提交和回滚','事务 ACID COMMIT ROLLBACK InnoDB', '事务把多个操作作为一个逻辑单元提交或撤销。InnoDB 提供事务能力，隔离级别会影响并发读取行为。异常后及时回滚，且不要让数据库事务跨越漫长的外部模型请求。','START TRANSACTION;\nUPDATE reading_progress SET ratio = 50 WHERE id = 1;\nROLLBACK; -- 演示撤销，不保留修改'),
('mysql-sql-injection','参数化查询如何防止 SQL 注入','SQL注入 占位符 参数绑定', '把用户文本直接拼进 SQL 会让数据混入语句结构。预编译参数用于传递值；表名、列名或排序方向通常不能作为值参数绑定，应从固定白名单中选择。','# PyMySQL 示例，在已有 cursor 上调用\ncursor.execute("SELECT title FROM notes WHERE id = %s", (7,))'),
('mysql-database-export','数据库备份与恢复演练','mysqldump 备份 恢复 数据迁移', '备份不仅要保存数据，还需要确认编码、结构和恢复步骤。修改大量知识前先做独立快照，并在测试环境验证恢复。包含用户与会话的备份不应提交到公共仓库。','-- 示例：备份一个专用测试库，使用 -p 交互输入密码\n-- mysqldump -u backup_user -p library_demo > library_demo.sql'),
],
'Docker': [
('docker-intro','镜像和容器到底有什么区别','镜像 容器 image container', '镜像是可复用的运行模板，容器是从镜像创建的运行实例。多个容器可以共享镜像，但各自有独立的可写层。删除容器会丢失未持久化在卷或外部系统中的数据。','docker image ls\ndocker container ls -a'),
('docker-architecture','Docker 客户端、守护进程与仓库','Docker 架构 daemon registry client', '命令行客户端把请求交给 Docker 守护进程，后者负责管理镜像、容器和网络。镜像仓库用于分发镜像。能访问守护进程的权限通常很高，不宜任意暴露管理接口。','docker version\ndocker info'),
('docker-desktop','Docker Desktop 与本地开发环境','Desktop Windows macOS 虚拟化', 'Docker Desktop 把容器管理工具和桌面运行环境整合起来。Windows 与 macOS 运行 Linux 容器时通常依赖虚拟化环境。安装后先检查服务是否可用，再排查项目构建问题。','docker version\ndocker compose version'),
('windows-docker-install','Windows 上的 Docker 与 WSL2','Windows WSL2 Linux容器', 'Windows 上开发 Linux 容器时，可使用支持 WSL2 的 Docker Desktop 环境。项目文件、路径映射和换行格式会影响开发体验。具体系统与版本要求请核对当前官方安装文档。','wsl --status\ndocker context ls'),
('docker-hello-world','用一次性容器验证环境','hello-world run --rm 验证', '先运行一个小型验证容器，可以区分引擎未启动、网络拉取失败和项目本身异常。--rm 在退出后清理容器，不会自动删除下载的镜像。','docker run --rm hello-world'),
('docker-container-usage','容器启动、停止与日志排查','run start stop logs exec', 'run 创建并启动新容器，start 启动已有容器，stop 请求正常停止。查看日志和退出码有助于排查应用启动失败。容器的主进程结束后，容器通常随之退出。','docker ps -a\ndocker logs --tail 50 library-web\ndocker stop library-web'),
('docker-image-usage','镜像标签、拉取和版本固定','pull image tag digest', '镜像标签是人类可读引用，但同一标签可以被重新指向。可复现部署应记录明确版本，必要时固定镜像摘要。精简基础镜像可降低体积，但还需考虑依赖兼容性。','docker pull python:3.11-slim\ndocker image inspect python:3.11-slim'),
('docker-container-connection','端口映射与容器网络','端口 -p 网络 localhost 容器互联', '容器端口与宿主机端口不同，-p 建立访问映射。应用在容器内一般应监听 0.0.0.0。Compose 网络中访问另一个服务使用服务名，容器内的 localhost 通常只指自身。','docker run --rm -p 127.0.0.1:8088:80 nginx:stable'),
('docker-repository','镜像仓库与命名空间','registry tag push 仓库', '镜像名称可以包含仓库域名、组织和标签。推送前要确认目标仓库和可见范围。构建产物不应包含 .env、访问令牌或个人数据库备份。','docker tag library-web:demo example/library-web:demo\n# 确认仓库与权限后再推送'),
('docker-dockerfile','Dockerfile 的层缓存与依赖安装','Dockerfile FROM COPY RUN 缓存', 'Dockerfile 描述镜像构建步骤。先复制依赖清单并安装，再复制业务代码，可以让源代码修改时复用依赖层缓存。使用 .dockerignore 排除模型缓存、密钥和临时文件。','FROM python:3.11-slim\nWORKDIR /app\nCOPY requirements.txt .\nRUN pip install --no-cache-dir -r requirements.txt\nCOPY app ./app'),
('docker-compose','Compose 如何编排后端和数据库','Compose services volumes depends_on', 'Compose 用声明文件描述服务、网络和持久卷，适合组织后端、数据库与模型服务。depends_on 不总等于应用已就绪；可结合健康检查和连接重试。服务间地址应使用服务名。','services:\n  web:\n    image: library-web:demo\n    ports:\n      - "127.0.0.1:8000:8000"'),
('docker-install-nginx','用 Nginx 提供静态网页','Nginx 静态文件 bind mount 只读', 'Nginx 容器可提供静态资源或作为反向代理。把静态目录以只读挂载方式提供给容器，可避免服务修改源文件。代理到其他服务时要注意网络和上游地址。','docker run --rm -p 127.0.0.1:8088:80 \\\n  --mount type=bind,src=/absolute/site,dst=/usr/share/nginx/html,readonly nginx:stable'),
('docker-install-mysql','MySQL 容器为什么需要持久卷','MySQL volume 数据持久化 环境变量', '数据库文件保存在容器可写层中，容器重建时容易丢失。命名卷可独立于容器保存数据。初始化密码应通过部署配置提供；已有卷中的数据库通常不会因修改初始化变量而重新初始化。','docker volume create library_mysql\n# 在部署配置中把卷挂载到 /var/lib/mysql'),
('docker-install-python','把 Python 应用放进容器','Python FastAPI Uvicorn 依赖部署', 'Python 容器应固定基础环境并安装运行依赖。FastAPI 在容器中可由 Uvicorn 启动，监听地址要允许容器网络访问。开发重载与生产进程管理应分别配置。','CMD ["python", "-m", "uvicorn", "app.main:app", "--host", "0.0.0.0", "--port", "8000"]'),
('docker-install-redis','Redis 容器与缓存数据','Redis 缓存 数据卷 网络', 'Redis 常用于缓存或短期状态。是否需要持久化取决于数据用途与恢复要求。服务只在应用网络内使用时通常不必把端口公开到宿主机；访问还需配置适当认证。','docker run --rm --name cache-demo redis:7-alpine'),
('docker-command-manual','查看容器资源与定位运行故障','stats inspect logs 诊断 内存 CPU', '先检查容器是否运行，再查看日志、健康状态和资源使用。应用无法连接数据库时，应依次确认服务名、端口、网络、就绪状态和凭据，而不是只反复重启。','docker compose ps\ndocker compose logs --tail 80\ndocker stats --no-stream'),
],
}
